import { SvgIconProps } from '../svg-icon';

export interface BrandProps
  extends Omit<
    SvgIconProps,
    | 'classes'
    | 'color'
    | 'component'
    | 'ref'
    | 'fontSize'
    | 'shapeRendering'
    | 'htmlColor'
    | 'children'
  > {
  /** Set the icon size */
  size?: 'xsmall' | 'small' | 'medium' | 'large' | 'xlarge';
  /** Set the icon variant */
  variant?: 'regular' | 'icon' | 'vertical';
  /** Set the icon color */
  colorType?: 'standard' | 'onColorBg' | 'onDarkBg';
  /** Set a data-testid to test your component */
  dataTestid?: string;
}
